import AppKit
import SwiftUI

public enum AppLogo {
    private static let base64Data = ""

    public static let image: NSImage = {
        if let data = Data(base64Encoded: base64Data), let img = NSImage(data: data) {
            return img
        }
        if let path = Bundle.main.path(forResource: "AppLogo", ofType: "png"), let img = NSImage(contentsOfFile: path) {
            return img
        }
        return NSImage()
    }()

    public static let menuBarImage: NSImage = {
        let original = image
        let targetHeight: CGFloat = 16
        let aspect = original.size.width / max(1, original.size.height)
        let targetWidth = targetHeight * aspect
        let size = NSSize(width: targetWidth, height: targetHeight)
        
        let resized = NSImage(size: size)
        resized.lockFocus()
        original.draw(in: NSRect(origin: .zero, size: size),
                      from: NSRect(origin: .zero, size: original.size),
                      operation: .copy,
                      fraction: 1.0)
        resized.unlockFocus()
        resized.isTemplate = true
        return resized
    }()
}

public struct AppLogoView: View {
    public var height: CGFloat
    public var opacity: Double

    public init(height: CGFloat = 16, opacity: Double = 1.0) {
        self.height = height
        self.opacity = opacity
    }

    public var body: some View {
        Image(nsImage: AppLogo.image)
            .resizable()
            .renderingMode(.template)
            .aspectRatio(contentMode: .fit)
            .frame(height: height)
            .opacity(opacity)
    }
}
